var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel comp = null;
foreach (var r in roots) {
    comp = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (comp != null) break;
}
if (comp == null) { Debug.LogError("comp is null"); return; }
var so = new UnityEditor.SerializedObject(comp);
so.Update();
string rootName = so.FindProperty("root").objectReferenceValue != null ? so.FindProperty("root").objectReferenceValue.name : "NULL";
string ratingName = so.FindProperty("ratingLabel").objectReferenceValue != null ? so.FindProperty("ratingLabel").objectReferenceValue.name : "NULL";
string scoreName = so.FindProperty("scoreLabel").objectReferenceValue != null ? so.FindProperty("scoreLabel").objectReferenceValue.name : "NULL";
string breakdownName = so.FindProperty("breakdownLabel").objectReferenceValue != null ? so.FindProperty("breakdownLabel").objectReferenceValue.name : "NULL";
string closeName = so.FindProperty("closeButton").objectReferenceValue != null ? so.FindProperty("closeButton").objectReferenceValue.name : "NULL";
Debug.Log("[Verify] root=" + rootName + " rating=" + ratingName + " score=" + scoreName + " breakdown=" + breakdownName + " close=" + closeName);
